class UploadFailureDiagnosticsTest {
    @Test
    void missingStatusAndRequestIdAreDiagnosedAtWarnWithoutDebug() {
        List<String> levels = new ArrayList<>();
        List<Object[]> calls = new ArrayList<>();
        var error = new BmcException(-1, null, "sensitive SDK message", null,
                new RuntimeException("sensitive wrapper", new UnknownHostException("sensitive hostname")));
        var chunk = new LogEventsChunker(TestFixtures.config()).chunk(TestFixtures.records(1)).get(0);
        UploadFailureDiagnostics.logFailure(logger(levels, calls, false), error, chunk, 15,
                "oracleobservability-test", TestFixtures.config(), "https://logs.example.com");
        assertEquals(List.of("warn"), levels);
        var details = (Map<?, ?>) calls.get(0)[1];
        assertEquals(-1, details.get("status"));
        assertNull(details.get("opcRequestId"));
        assertEquals("oracleobservability-test", details.get("clientRequestId"));
        assertEquals(false, details.get("httpStatusAvailable"));
        assertEquals(1, details.get("records"));
        assertEquals(15L, details.get("latencyMs"));
        var failure = (Map<?, ?>) details.get("failure");
        assertEquals("DNS", failure.get("category"));
        assertTrue(failure.get("causeTypes").toString().contains("java.net.UnknownHostException"));
        assertFalse(details.toString().contains("sensitive"));
        assertFalse(failure.containsKey("stackLocations"));
    }

    @Test
    void debugCapturesLocationsWithoutRawCauseMessagesOrThrowableArguments() {
        List<String> levels = new ArrayList<>();
        List<Object[]> calls = new ArrayList<>();
        var root = new SSLHandshakeException("password=private-value customer log contents");
        root.setStackTrace(new StackTraceElement[] {
            new StackTraceElement("example.TlsClient", "handshake", "TlsClient.java", 42)
        });
        var error = new BmcException(-1, null, "customer log contents", null, root);
        var chunk = new LogEventsChunker(TestFixtures.config()).chunk(TestFixtures.records(1)).get(0);
        UploadFailureDiagnostics.logFailure(logger(levels, calls, true), error, chunk, 8,
                "oracleobservability-test", TestFixtures.config(), "https://logs.example.com");
        assertEquals(List.of("warn", "debug"), levels);
        String debug = calls.get(1)[2].toString();
        assertTrue(debug.contains("example.TlsClient.handshake:42"));
        assertFalse(debug.contains("private-value"));
        assertFalse(debug.contains("customer log contents"));
        for (Object[] call : calls) {
            for (Object value : call) { assertFalse(value instanceof Throwable); }
        }
    }

    @ParameterizedTest
    @MethodSource("transportFailures")
    void classifiesNestedTransportFailures(Throwable cause, String category) {
        var error = new BmcException(-1, null, "unavailable", null, new RuntimeException("wrapper", cause));
        assertEquals(category, UploadFailureDiagnostics.causeDetails(error, false).get("category"));
    }

    static Stream<Arguments> transportFailures() {
        return Stream.of(
                Arguments.of(new UnknownHostException(), "DNS"),
                Arguments.of(new SSLHandshakeException("certificate failure"), "TLS"),
                Arguments.of(new SocketTimeoutException(), "TIMEOUT"),
                Arguments.of(new NoRouteToHostException(), "ROUTING"),
                Arguments.of(new ConnectException(), "CONNECT"),
                Arguments.of(new NoClassDefFoundError("missing provider"), "PLUGIN_CLASSPATH"),
                Arguments.of(new SecurityException(), "CLIENT_SECURITY"),
                Arguments.of(new SocketException(), "SOCKET"));
    }

    @Test
    void httpErrorsAndUnknownClientErrorsDoNotClaimASpecificNetworkCause() {
        assertEquals("HTTP_RESPONSE", UploadFailureDiagnostics.causeDetails(
                new BmcException(403, "NotAuthorized", "sensitive body", "request-id"), false).get("category"));
        assertEquals("CLIENT_OR_TRANSPORT", UploadFailureDiagnostics.causeDetails(
                new IllegalStateException("sensitive body"), false).get("category"));
    }

    @Test
    void causeCyclesDepthAndStackLocationsAreBounded() {
        var first = new RuntimeException("first");
        var second = new RuntimeException("second", first);
        first.initCause(second);
        var cycle = UploadFailureDiagnostics.causeDetails(first, true);
        assertEquals(2, ((List<?>) cycle.get("causeTypes")).size());
        assertEquals(true, cycle.get("causeChainTruncated"));
        Throwable deep = new RuntimeException();
        for (int i = 0; i < 30; i++) { deep = new RuntimeException("secret", deep); }
        var details = UploadFailureDiagnostics.causeDetails(deep, true);
        assertEquals(12, ((List<?>) details.get("causeTypes")).size());
        assertEquals(true, details.get("causeChainTruncated"));
        for (Object item : (List<?>) details.get("stackLocations")) {
            assertTrue(((List<?>) ((Map<?, ?>) item).get("locations")).size() <= 6);
        }
    }

    @Test
    void transportContextStripsUserinfoPathQueryAndSensitiveDestinationSettings() {
        var props = TestFixtures.properties();
        props.put(OracleObservabilitySinkConfig.PROXY_HOST, "proxy.example.com");
        props.put(OracleObservabilitySinkConfig.PROXY_PORT, "8080");
        var context = UploadFailureDiagnostics.transportContext(new OracleObservabilitySinkConfig(props),
                "https://user:secret@logs.example.com:443/namespaces/private-namespace?token=secret#private");
        assertEquals("https://logs.example.com:443", context.get("endpoint"));
        assertEquals("proxy.example.com", context.get("proxyHost"));
        assertEquals(8080, context.get("proxyPort"));
        assertEquals(5000, context.get("connectTimeoutMs"));
        assertEquals(15000, context.get("readTimeoutMs"));
        assertFalse(context.toString().contains("secret"));
        assertFalse(context.toString().contains("namespace"));
        assertFalse(context.toString().contains("ocid1"));
        assertFalse(context.toString().contains("test-config"));
        for (String endpoint : new String[] {"not a URI with secret", "file:///private/secret"}) {
            assertEquals("[unavailable]", UploadFailureDiagnostics.transportContext(
                    TestFixtures.config(), endpoint).get("endpoint"));
        }
        var defaults = UploadFailureDiagnostics.transportContext(TestFixtures.config(), null);
        assertEquals("[unavailable]", defaults.get("endpoint"));
        assertEquals(false, defaults.get("explicitProxyConfigured"));
        assertFalse(defaults.containsKey("proxyHost"));
    }

    private static Logger logger(List<String> levels, List<Object[]> calls, boolean debug) {
        return (Logger) Proxy.newProxyInstance(Logger.class.getClassLoader(), new Class<?>[] {Logger.class},
                (proxy, method, args) -> {
                    if (method.getName().equals("isDebugEnabled")) { return debug; }
                    if (method.getName().equals("warn") || method.getName().equals("debug")) {
                        levels.add(method.getName());
                        calls.add(args);
                        return null;
                    }
                    throw new UnsupportedOperationException(method.getName());
                });
    }
}
